-- =============================================================================
-- Migration 0042: K.3 Theorie C — De functie arcsin
-- =============================================================================
-- Gegenereerd door scripts/k3c-content.ts — niet met de hand bewerken.
--
-- Het derde theorieblok van K.3, met de inverse van de sinus:
--
--     f(x) = 1/√(1 - x²)   geeft   F(x) = arcsin(x) + c
--     g(x) = arcsin(x)     geeft   g'(x) = 1/√(1 - x²)
--
-- Zeven clusters: exacte waarden, vergelijkingen, de standaardvorm, een kern
-- onder de wortel, partieel integreren met arcsin en arctan, bepaalde
-- integralen en vlakdelen.
--
-- Eigen topics en eigen clusters, zodat de controles aan het eind van de eerdere
-- K-migraties blijven kloppen en die migraties herhaalbaar blijven.
--
-- Eigen oefenvragen, geen boekopgaven. De 19 vragen met een integraal worden
-- nagerekend door src/content/primitieven.test.ts (content/hoofdstuk-k/k3c.json);
-- de zeven vragen over de functie zelf hebben geen integraal en staan daar niet in.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 4 topics, 7 clusters
--   • 26 vragen met elk 4 stappen (104 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k3c_arcsinus', $ksql$De functie arcsin$ksql$, 23, 'vergelijkingen'),
  ('k3c_primitiveren', $ksql$Primitiveren naar arcsin$ksql$, 24, 'primitiveren'),
  ('k3c_bepaald', $ksql$Bepaalde integralen met arcsin$ksql$, 25, 'integralen'),
  ('k3c_toepassing', $ksql$Vlakdelen met arcsin$ksql$, 26, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Exacte waarden van arcsin$ksql$, 1),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Vergelijkingen met arcsin oplossen$ksql$, 2),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$De standaardvorm 1/√(1 - x²) primitiveren$ksql$, 1),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Een kern onder de wortel$ksql$, 2),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$arcsin en arctan partieel integreren$ksql$, 3),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bepaalde integralen met arcsin$ksql$, 1),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Oppervlakte en de waarde van p$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
