SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right)$$ksql$, $ksql$1/3 pi$ksql$, $ksql$\tfrac{1}{3}\pi$ksql$, 1, 1, ARRAY[$ksql$pi/3$ksql$, $ksql$(1/3)pi$ksql$, $ksql$1/3pi$ksql$]::text[]),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) + \arcsin(1)$$ksql$, $ksql$1/4 pi$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 2, 2, ARRAY[$ksql$pi/4$ksql$, $ksql$(1/4)pi$ksql$, $ksql$1/4pi$ksql$]::text[]),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, $ksql$1/6 pi$ksql$, $ksql$\tfrac{1}{6}\pi$ksql$, 3, 3, ARRAY[$ksql$pi/6$ksql$, $ksql$(1/6)pi$ksql$, $ksql$1/6pi$ksql$]::text[]),
