  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \tfrac{4}{5}\pi$$ksql$, $ksql$geen oplossing$ksql$, $ksql$\text{geen oplossing}$ksql$, 1, 2, ARRAY[$ksql$er is geen oplossing$ksql$, $ksql$geen$ksql$, $ksql$geen oplossingen$ksql$]::text[]),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $2\arcsin(x + 1) = \tfrac{2}{3}\pi$$ksql$, $ksql$1/2 sqrt(3) - 1$ksql$, $ksql$x = \tfrac{1}{2}\sqrt{3} - 1$ksql$, 2, 3, ARRAY[$ksql$x = 1/2 sqrt(3) - 1$ksql$, $ksql$sqrt(3)/2 - 1$ksql$, $ksql$x = sqrt(3)/2 - 1$ksql$, $ksql$-1 + 1/2 sqrt(3)$ksql$]::text[]),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin\left(x^{2} - 1\right) = -\tfrac{1}{6}\pi$$ksql$, $ksql$x = 1/2 sqrt(2) of x = -1/2 sqrt(2)$ksql$, $ksql$x = \tfrac{1}{2}\sqrt{2} \ \vee \ x = -\tfrac{1}{2}\sqrt{2}$ksql$, 3, 4, ARRAY[$ksql$x = -1/2 sqrt(2) of x = 1/2 sqrt(2)$ksql$, $ksql$1/2 sqrt(2) of -1/2 sqrt(2)$ksql$, $ksql$x = ±1/2 sqrt(2)$ksql$, $ksql$x = sqrt(2)/2 of x = -sqrt(2)/2$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3}{\sqrt{1 - x^{2}}}$$ksql$, $ksql$3arcsin(x) + c$ksql$, $ksql$F(x) = 3\arcsin(x) + c$ksql$, 1, 1, ARRAY[$ksql$3 arcsin(x) + c$ksql$, $ksql$3asin(x) + c$ksql$, $ksql$3 asin(x) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 16x^{2}}}$$ksql$, $ksql$1/4 arcsin(4x) + c$ksql$, $ksql$F(x) = \tfrac{1}{4}\arcsin(4x) + c$ksql$, 1, 2, ARRAY[$ksql$arcsin(4x)/4 + c$ksql$, $ksql$(1/4)arcsin(4x) + c$ksql$, $ksql$1/4 asin(4x) + c$ksql$, $ksql$0,25 arcsin(4x) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$$ksql$, $ksql$arcsin(1/2 x) + c$ksql$, $ksql$F(x) = \arcsin\left(\tfrac{1}{2}x\right) + c$ksql$, 2, 3, ARRAY[$ksql$arcsin(x/2) + c$ksql$, $ksql$asin(x/2) + c$ksql$, $ksql$asin(1/2 x) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6}{\sqrt{9 - 4x^{2}}}$$ksql$, $ksql$3arcsin(2/3 x) + c$ksql$, $ksql$F(x) = 3\arcsin\left(\tfrac{2}{3}x\right) + c$ksql$, 2, 4, ARRAY[$ksql$3 arcsin(2x/3) + c$ksql$, $ksql$3arcsin(2x/3) + c$ksql$, $ksql$3 asin(2x/3) + c$ksql$, $ksql$3asin(2/3 x) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4x - x^{2} - 3}}$$ksql$, $ksql$arcsin(x - 2) + c$ksql$, $ksql$F(x) = \arcsin(x - 2) + c$ksql$, 3, 5, ARRAY[$ksql$asin(x - 2) + c$ksql$, $ksql$arcsin(x-2) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{\sqrt{1 - x^{4}}}$$ksql$, $ksql$arcsin(x^2) + c$ksql$, $ksql$F(x) = \arcsin\left(x^{2}\right) + c$ksql$, 1, 1, ARRAY[$ksql$asin(x^2) + c$ksql$, $ksql$arcsin(x²) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\sqrt{1 - \mathrm{e}^{2x}}}$$ksql$, $ksql$arcsin(e^x) + c$ksql$, $ksql$F(x) = \arcsin\left(\mathrm{e}^{x}\right) + c$ksql$, 2, 2, ARRAY[$ksql$asin(e^x) + c$ksql$, $ksql$arcsin(e^(x)) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\arcsin^{2}(x)}{\sqrt{1 - x^{2}}}$$ksql$, $ksql$1/3 arcsin^3(x) + c$ksql$, $ksql$F(x) = \tfrac{1}{3}\arcsin^{3}(x) + c$ksql$, 3, 3, ARRAY[$ksql$arcsin(x)^3/3 + c$ksql$, $ksql$1/3 arcsin(x)^3 + c$ksql$, $ksql$(1/3)asin(x)^3 + c$ksql$, $ksql$1/3 asin^3(x) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{4 - \ln^{2}(x)}}$$ksql$, $ksql$arcsin(1/2 ln(x)) + c$ksql$, $ksql$F(x) = \arcsin\left(\tfrac{1}{2}\ln(x)\right) + c$ksql$, 3, 4, ARRAY[$ksql$arcsin(ln(x)/2) + c$ksql$, $ksql$asin(ln(x)/2) + c$ksql$, $ksql$asin(1/2 ln(x)) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(2x)$$ksql$, $ksql$x arcsin(2x) + 1/2 sqrt(1 - 4x^2) + c$ksql$, $ksql$F(x) = x\arcsin(2x) + \tfrac{1}{2}\sqrt{1 - 4x^{2}} + c$ksql$, 1, 1, ARRAY[$ksql$x asin(2x) + 1/2 sqrt(1 - 4x^2) + c$ksql$, $ksql$x arcsin(2x) + sqrt(1 - 4x^2)/2 + c$ksql$, $ksql$x*arcsin(2x) + 1/2*sqrt(1-4x^2) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(3x)$$ksql$, $ksql$x arctan(3x) - 1/6 ln(9x^2 + 1) + c$ksql$, $ksql$F(x) = x\arctan(3x) - \tfrac{1}{6}\ln\left(9x^{2} + 1\right) + c$ksql$, 2, 2, ARRAY[$ksql$x atan(3x) - 1/6 ln(9x^2 + 1) + c$ksql$, $ksql$x arctan(3x) - ln(9x^2 + 1)/6 + c$ksql$, $ksql$x*arctan(3x) - 1/6*ln(9x^2+1) + c$ksql$]::text[]),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \arcsin(x)\,\mathrm{d}x$$ksql$, $ksql$1/2 pi - 1$ksql$, $ksql$\tfrac{1}{2}\pi - 1$ksql$, 3, 3, ARRAY[$ksql$pi/2 - 1$ksql$, $ksql$(1/2)pi - 1$ksql$, $ksql$-1 + 1/2 pi$ksql$, $ksql$1/2pi - 1$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/4 pi$ksql$, $ksql$\tfrac{1}{4}\pi$ksql$, 1, 1, ARRAY[$ksql$pi/4$ksql$, $ksql$(1/4)pi$ksql$, $ksql$1/4pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}} \dfrac{1}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/12 pi$ksql$, $ksql$\tfrac{1}{12}\pi$ksql$, 2, 2, ARRAY[$ksql$pi/12$ksql$, $ksql$(1/12)pi$ksql$, $ksql$1/12pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{16 - x^{2}}}\,\mathrm{d}x$$ksql$, $ksql$1/3 pi$ksql$, $ksql$\tfrac{1}{3}\pi$ksql$, 2, 3, ARRAY[$ksql$pi/3$ksql$, $ksql$(1/3)pi$ksql$, $ksql$1/3pi$ksql$]::text[]),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{6}} \dfrac{x}{\sqrt{9 - x^{4}}}\,\mathrm{d}x$$ksql$, $ksql$1/12 pi$ksql$, $ksql$\tfrac{1}{12}\pi$ksql$, 3, 4, ARRAY[$ksql$pi/12$ksql$, $ksql$(1/12)pi$ksql$, $ksql$1/12pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3}{\sqrt{9 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1/2 pi$ksql$, $ksql$\tfrac{1}{2}\pi$ksql$, 2, 1, ARRAY[$ksql$pi/2$ksql$, $ksql$(1/2)pi$ksql$, $ksql$1/2pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x}{\sqrt{16 - x^{4}}}$, de $x$-as en de lijn $x = \sqrt{2}$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1/12 pi$ksql$, $ksql$\tfrac{1}{12}\pi$ksql$, 2, 2, ARRAY[$ksql$pi/12$ksql$, $ksql$(1/12)pi$ksql$, $ksql$1/12pi$ksql$]::text[]),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{\sqrt{25 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 5$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, $ksql$2 1/2 sqrt(2)$ksql$, $ksql$p = 2\tfrac{1}{2}\sqrt{2}$ksql$, 3, 3, ARRAY[$ksql$p = 2 1/2 sqrt(2)$ksql$, $ksql$5/2 sqrt(2)$ksql$, $ksql$p = 5/2 sqrt(2)$ksql$, $ksql$2,5 sqrt(2)$ksql$, $ksql$5 sqrt(2)/2$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. De vraag is dus: welke hoek tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ heeft sinus $\tfrac{1}{2}\sqrt{3}$?$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right)$$ksql$, 3, $ksql$$\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\tfrac{1}{3}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus $\arcsin\left(\tfrac{1}{2}\sqrt{3}\right) = \tfrac{1}{3}\pi$. Let op: $\tfrac{2}{3}\pi$ heeft dezelfde sinus, maar valt buiten het bereik.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) + \arcsin(1)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) + \arcsin(1)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Zoek de twee hoeken apart op en tel ze daarna pas bij elkaar op.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) + \arcsin(1)$$ksql$, 2, $ksql$Uit de tabel die je uit het hoofd kent: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, $\sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$. Omdat $\sin$ oneven is, hoort bij een negatief getal dezelfde hoek met een minteken. Dus $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) = -\tfrac{1}{4}\pi$ en $\arcsin(1) = \tfrac{1}{2}\pi$. Die laatste ligt nog net in het bereik, want dat is een gesloten interval.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(-\tfrac{1}{2}\sqrt{2}\right) + \arcsin(1)$$ksql$, 3, $ksql$Optellen: $-\tfrac{1}{4}\pi + \tfrac{1}{2}\pi = -\tfrac{1}{4}\pi + \tfrac{2}{4}\pi = \tfrac{1}{4}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 1, $ksql$$\arcsin(a)$ is de hoek $t$ met $\sin(t) = a$ én $-\tfrac{1}{2}\pi \le t \le \tfrac{1}{2}\pi$. Dat laatste stukje is de hele truc: er zijn oneindig veel hoeken met dezelfde sinus, maar $\arcsin$ kiest er altijd één uit dat gebied. En omdat een sinus nooit buiten $[-1, 1]$ komt, is dat ook meteen het domein van $\arcsin$. Het ligt voor de hand om $\tfrac{5}{6}\pi$ te antwoorden, maar dat is fout: $\tfrac{5}{6}\pi$ ligt niet tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, en dat is wel waar $\arcsin$ altijd uitkomt. Reken daarom van binnen naar buiten.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 2, $ksql$Eerst de binnenkant: $\sin\left(\tfrac{5}{6}\pi\right) = \sin\left(\pi - \tfrac{5}{6}\pi\right) = \sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$, want twee hoeken die samen $\pi$ zijn hebben dezelfde sinus.$ksql$),
  ('k3c_arcsinus', 'k3c_waarden', $ksql$Bereken exact: $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right)$$ksql$, 3, $ksql$Dan de buitenkant: $\arcsin\left(\tfrac{1}{2}\right) = \tfrac{1}{6}\pi$. Die hoek ligt wél in het bereik. Dus $\arcsin\left(\sin\left(\tfrac{5}{6}\pi\right)\right) = \tfrac{1}{6}\pi$, en niet $\tfrac{5}{6}\pi$. Andersom, $\sin(\arcsin(a))$, gaat altijd goed zolang $a$ tussen $-1$ en $1$ ligt.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{6}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin$ van iets is gelijk aan een hoek → neem aan beide kanten de sinus.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{6}\pi$$ksql$, 1, $ksql$Omdat $\arcsin$ en $\sin$ elkaars inverse zijn, is $\arcsin(x) = \tfrac{1}{6}\pi$ hetzelfde als $x = \sin\left(\tfrac{1}{6}\pi\right)$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{6}\pi$$ksql$, 2, $ksql$Controleer eerst of de rechterkant kán: $\tfrac{1}{6}\pi$ ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing. Uit de tabel: $\sin\left(\tfrac{1}{6}\pi\right) = \tfrac{1}{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin(x) = \tfrac{1}{6}\pi$$ksql$, 3, $ksql$Dus $x = \tfrac{1}{2}$. Die ligt netjes in $[-1, 1]$, het domein van $\arcsin$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \tfrac{4}{5}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin$ van iets is gelijk aan een hoek → kijk eerst of die hoek überhaupt kan.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \tfrac{4}{5}\pi$$ksql$, 1, $ksql$Het bereik van $\arcsin$ is $\left[-\tfrac{1}{2}\pi, \tfrac{1}{2}\pi\right]$: wat je ook invult, er komt altijd een hoek tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$ uit.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \tfrac{4}{5}\pi$$ksql$, 2, $ksql$En $\tfrac{4}{5}\pi$ is groter dan $\tfrac{1}{2}\pi$, dus die waarde wordt nooit bereikt.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los op: $\arcsin(x) = \tfrac{4}{5}\pi$$ksql$, 3, $ksql$De vergelijking heeft geen oplossing. Val niet in de val om $x = \sin\left(\tfrac{4}{5}\pi\right)$ op te schrijven: dat getal bestaat wel, maar zijn $\arcsin$ is $\tfrac{1}{5}\pi$ en niet $\tfrac{4}{5}\pi$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $2\arcsin(x + 1) = \tfrac{2}{3}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: er staat een getal vóór de $\arcsin$ → maak eerst de $\arcsin$ alleen, daarna de kern, en pas als laatste $x$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $2\arcsin(x + 1) = \tfrac{2}{3}\pi$$ksql$, 1, $ksql$Deel beide kanten door $2$: $\arcsin(x + 1) = \tfrac{1}{3}\pi$. Sinus nemen aan beide kanten geeft $x + 1 = \sin\left(\tfrac{1}{3}\pi\right)$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $2\arcsin(x + 1) = \tfrac{2}{3}\pi$$ksql$, 2, $ksql$$\tfrac{1}{3}\pi$ ligt in het bereik van $\arcsin$, dus er is een oplossing, en $\sin\left(\tfrac{1}{3}\pi\right) = \tfrac{1}{2}\sqrt{3}$. Dus $x + 1 = \tfrac{1}{2}\sqrt{3}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $2\arcsin(x + 1) = \tfrac{2}{3}\pi$$ksql$, 3, $ksql$Haal er $1$ af: $x = \tfrac{1}{2}\sqrt{3} - 1 \approx -0{,}13$. Controleer de kern: $x + 1 = \tfrac{1}{2}\sqrt{3} \approx 0{,}87$ ligt in $[-1, 1]$, dus het antwoord mag.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin\left(x^{2} - 1\right) = -\tfrac{1}{6}\pi$$ksql$, 0, $ksql$Hier speelt alleen deel 3 van de driedeling: de goede oplossingsmethode gebruiken. Er staat geen integraal in deze opgave; je hebt alleen nodig wat $\arcsin$ betekent. Buitenste schil: $\arcsin$ van een kern is gelijk aan een hoek → eerst de kern vrijmaken. De kern is hier een kwadraat min een getal, dus let op: dat geeft straks twee oplossingen.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin\left(x^{2} - 1\right) = -\tfrac{1}{6}\pi$$ksql$, 1, $ksql$Sinus nemen aan beide kanten: $x^{2} - 1 = \sin\left(-\tfrac{1}{6}\pi\right) = -\tfrac{1}{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin\left(x^{2} - 1\right) = -\tfrac{1}{6}\pi$$ksql$, 2, $ksql$Dus $x^{2} = 1 - \tfrac{1}{2} = \tfrac{1}{2}$. Een kwadraat gelijk aan een positief getal geeft twee oplossingen: $x = \sqrt{\tfrac{1}{2}} = \tfrac{1}{2}\sqrt{2}$ of $x = -\tfrac{1}{2}\sqrt{2}$.$ksql$),
  ('k3c_arcsinus', 'k3c_vergelijking', $ksql$Los exact op: $\arcsin\left(x^{2} - 1\right) = -\tfrac{1}{6}\pi$$ksql$, 3, $ksql$Dus $x = \tfrac{1}{2}\sqrt{2} \ \vee \ x = -\tfrac{1}{2}\sqrt{2}$. Allebei kloppen ze, want $\left(\pm\tfrac{1}{2}\sqrt{2}\right)^{2} - 1 = \tfrac{1}{2} - 1 = -\tfrac{1}{2}$, en dat ligt in $[-1, 1]$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3}{\sqrt{1 - x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3}{\sqrt{1 - x^{2}}}$$ksql$, 1, $ksql$Onder de wortel staat al kaal $1 - x^{2}$, dus de kern is $x$ en $a = 1$: er valt niets te herschrijven. Het getal $3$ zet je zolang buiten de integraal: $\int \dfrac{3}{\sqrt{1 - x^{2}}}\,\mathrm{d}x = 3\int \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3}{\sqrt{1 - x^{2}}}$$ksql$, 2, $ksql$De standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$ geeft $\arcsin(x)$. Omdat $a = 1$ is, hoef je niet te delen.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{3}{\sqrt{1 - x^{2}}}$$ksql$, 3, $ksql$Zet de $3$ er weer voor: $F(x) = 3\arcsin(x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 16x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 16x^{2}}}$$ksql$, 1, $ksql$Schrijf $16x^{2}$ als een kwadraat: $16x^{2} = (4x)^{2}$. Er staat dus $\dfrac{1}{\sqrt{1 - (4x)^{2}}}$, met kern $4x$ en $a = 4$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 16x^{2}}}$$ksql$, 2, $ksql$De standaardvorm geeft $\arcsin(4x)$. De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Hier is $a = 4$, dus er komt $\tfrac{1}{4}$ voor.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{1 - 16x^{2}}}$$ksql$, 3, $ksql$Dus $F(x) = \tfrac{1}{4}\arcsin(4x) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{a^{2} - x^{2}}$ in de noemer → nog geen standaardvorm, want achter de $1$ hoort een min en vóór het kwadraat een $1$. Haal eerst $a$ buiten de wortel: $\sqrt{a^{2} - x^{2}} = a\sqrt{1 - \left(\tfrac{x}{a}\right)^{2}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$$ksql$, 1, $ksql$Haal de $2$ buiten de wortel: $\sqrt{4 - x^{2}} = \sqrt{4\left(1 - \tfrac{x^{2}}{4}\right)} = 2\sqrt{1 - \left(\tfrac{1}{2}x\right)^{2}}$. Dus $f(x) = \dfrac{\tfrac{1}{2}}{\sqrt{1 - \left(\tfrac{1}{2}x\right)^{2}}}$, met kern $\tfrac{1}{2}x$ en $a = \tfrac{1}{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$$ksql$, 2, $ksql$De standaardvorm geeft $\arcsin\left(\tfrac{1}{2}x\right)$. De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Delen door $\tfrac{1}{2}$ is vermenigvuldigen met $2$, dus $\dfrac{1}{\sqrt{1 - \left(\frac{1}{2}x\right)^{2}}}$ geeft $2\arcsin\left(\tfrac{1}{2}x\right)$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4 - x^{2}}}$$ksql$, 3, $ksql$Zet de $\tfrac{1}{2}$ er weer voor: $F(x) = \tfrac{1}{2} \cdot 2\arcsin\left(\tfrac{1}{2}x\right) + c = \arcsin\left(\tfrac{1}{2}x\right) + c$. De twee factoren vallen tegen elkaar weg — dat is bij $\dfrac{1}{\sqrt{a^{2} - x^{2}}}$ altijd zo. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6}{\sqrt{9 - 4x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met $\sqrt{a^{2} - x^{2}}$ in de noemer → nog geen standaardvorm, want achter de $1$ hoort een min en vóór het kwadraat een $1$. Haal eerst $a$ buiten de wortel: $\sqrt{a^{2} - x^{2}} = a\sqrt{1 - \left(\tfrac{x}{a}\right)^{2}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6}{\sqrt{9 - 4x^{2}}}$$ksql$, 1, $ksql$Haal de $9$ buiten de wortel: $\sqrt{9 - 4x^{2}} = 3\sqrt{1 - \tfrac{4x^{2}}{9}} = 3\sqrt{1 - \left(\tfrac{2}{3}x\right)^{2}}$, want $\tfrac{4x^{2}}{9} = \left(\tfrac{2}{3}x\right)^{2}$. Dus $f(x) = \dfrac{2}{\sqrt{1 - \left(\frac{2}{3}x\right)^{2}}}$, met kern $\tfrac{2}{3}x$ en $a = \tfrac{2}{3}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6}{\sqrt{9 - 4x^{2}}}$$ksql$, 2, $ksql$De standaardvorm geeft $\arcsin\left(\tfrac{2}{3}x\right)$. De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Delen door $\tfrac{2}{3}$ is vermenigvuldigen met $\tfrac{3}{2}$, dus er komt $\tfrac{3}{2}\arcsin\left(\tfrac{2}{3}x\right)$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{6}{\sqrt{9 - 4x^{2}}}$$ksql$, 3, $ksql$Zet de $2$ er weer voor: $F(x) = 2 \cdot \tfrac{3}{2}\arcsin\left(\tfrac{2}{3}x\right) + c = 3\arcsin\left(\tfrac{2}{3}x\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4x - x^{2} - 3}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat een polynoom waar geen kwadraat in te zien is → eerst kwadraatafsplitsen, net als bij $\arctan$, en dan pas kijken welke standaardvorm erbij hoort.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4x - x^{2} - 3}}$$ksql$, 1, $ksql$Zet de termen op volgorde en haal $-1$ buiten haakjes: $4x - x^{2} - 3 = -\left(x^{2} - 4x + 3\right)$. Kwadraatafsplitsen: de helft van $-4$ is $-2$, dus $x^{2} - 4x + 3 = (x - 2)^{2} - 1$. Samen: $4x - x^{2} - 3 = -\left((x - 2)^{2} - 1\right) = 1 - (x - 2)^{2}$.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4x - x^{2} - 3}}$$ksql$, 2, $ksql$Er staat nu $f(x) = \dfrac{1}{\sqrt{1 - (x - 2)^{2}}}$: precies de standaardvorm, met kern $x - 2$ en $a = 1$. De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Hier is $a = 1$, dus delen verandert niets.$ksql$),
  ('k3c_primitiveren', 'k3c_standaard', $ksql$Primitiveer: $f(x) = \dfrac{1}{\sqrt{4x - x^{2} - 3}}$$ksql$, 3, $ksql$Dus $F(x) = \arcsin(x - 2) + c$. Dit bestaat alleen waar $-1 \le x - 2 \le 1$, dus voor $1 \le x \le 3$ — en daarbuiten is de wortel ook niet te trekken. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{\sqrt{1 - x^{4}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $1$ min het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g) + c$ ben je er in één stap.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{\sqrt{1 - x^{4}}}$$ksql$, 1, $ksql$$x^{4}$ is het kwadraat van $x^{2}$, dus er staat $\dfrac{2x}{\sqrt{1 - \left(x^{2}\right)^{2}}}$. Neem $g(x) = x^{2}$; dan is $g'(x) = 2x$, en dat staat precies in de teller.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{\sqrt{1 - x^{4}}}$$ksql$, 2, $ksql$Naar $g$ staat er dus $\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g$, en dat is de standaardvorm: $\arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{2x}{\sqrt{1 - x^{4}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(x^{2}\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\sqrt{1 - \mathrm{e}^{2x}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $1$ min het kwadraat van iets anders dan $x$, en de afgeleide daarvan staat in de teller → substitutie. Met $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g) + c$ ben je er in één stap.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\sqrt{1 - \mathrm{e}^{2x}}}$$ksql$, 1, $ksql$Schrijf $\mathrm{e}^{2x}$ als een kwadraat: $\mathrm{e}^{2x} = \left(\mathrm{e}^{x}\right)^{2}$. Neem $g(x) = \mathrm{e}^{x}$; dan is $g'(x) = \mathrm{e}^{x}$ — de e-macht is zijn eigen afgeleide — en die staat in de teller.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\sqrt{1 - \mathrm{e}^{2x}}}$$ksql$, 2, $ksql$Naar $g$ staat er $\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\mathrm{e}^{x}}{\sqrt{1 - \mathrm{e}^{2x}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(\mathrm{e}^{x}\right) + c$. Dit bestaat alleen waar $\mathrm{e}^{x} \le 1$, dus voor $x \le 0$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\arcsin^{2}(x)}{\sqrt{1 - x^{2}}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: $\arcsin(x)$ staat zelf in de teller en $\dfrac{1}{\sqrt{1 - x^{2}}}$ is zijn eigen afgeleide → substitutie met $g(x) = \arcsin(x)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\arcsin^{2}(x)}{\sqrt{1 - x^{2}}}$$ksql$, 1, $ksql$Neem $g(x) = \arcsin(x)$, dan is $g'(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$. Er staat dus $f(x) = g^{2} \cdot g'$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\arcsin^{2}(x)}{\sqrt{1 - x^{2}}}$$ksql$, 2, $ksql$Primitiveer naar $g$ met de machtsregel: $\int g^{2}\,\mathrm{d}g = \tfrac{1}{3}g^{3}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{\arcsin^{2}(x)}{\sqrt{1 - x^{2}}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \tfrac{1}{3}\arcsin^{3}(x) + c$. Hier komt dus géén nieuwe $\arcsin$ bij; de $\arcsin$ die er al stond is de kern. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{4 - \ln^{2}(x)}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: onder de wortel staat $\ln^{2}(x)$ en de afgeleide van $\ln(x)$ is $\tfrac{1}{x}$, en die staat als factor vooraan → substitutie. Maar de wortel is nog niet van de vorm $\sqrt{1 - g^{2}}$, dus eerst de $4$ eruit halen.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{4 - \ln^{2}(x)}}$$ksql$, 1, $ksql$Haal de $4$ buiten de wortel: $\sqrt{4 - \ln^{2}(x)} = 2\sqrt{1 - \left(\tfrac{1}{2}\ln(x)\right)^{2}}$. Neem $g(x) = \tfrac{1}{2}\ln(x)$, dan is $g'(x) = \dfrac{1}{2x}$. Er staat dus $f(x) = \dfrac{\tfrac{1}{2x}}{\sqrt{1 - g^{2}}} = \dfrac{g'}{\sqrt{1 - g^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{4 - \ln^{2}(x)}}$$ksql$, 2, $ksql$Dat is de standaardvorm naar $g$: $\int \dfrac{g'}{\sqrt{1 - g^{2}}}\,\mathrm{d}x = \arcsin(g)$.$ksql$),
  ('k3c_primitiveren', 'k3c_kern', $ksql$Primitiveer: $f(x) = \dfrac{1}{x\sqrt{4 - \ln^{2}(x)}}$$ksql$, 3, $ksql$Schrijf $g$ terug: $F(x) = \arcsin\left(\tfrac{1}{2}\ln(x)\right) + c$. Dit bestaat alleen waar $-2 \le \ln(x) \le 2$, dus voor $\mathrm{e}^{-2} \le x \le \mathrm{e}^{2}$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(2x)$$ksql$, 1, $ksql$Er staat maar één factor, dus maak er zelf een product van: $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \arcsin(2x)$. Met de kettingregel is $g'(x) = \dfrac{2}{\sqrt{1 - 4x^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arcsin(2x)\,\mathrm{d}x = x\arcsin(2x) - \int \dfrac{2x}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$. De nieuwe integraal is makkelijker: er staat een $x$ in de teller en $x^{2}$ onder de wortel.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arcsin(2x)$$ksql$, 3, $ksql$Die laatste integraal is $-\tfrac{1}{2}\sqrt{1 - 4x^{2}}$, want $\left[\sqrt{1 - 4x^{2}}\right]' = \dfrac{-4x}{\sqrt{1 - 4x^{2}}}$ en dat is $-2$ keer de integrand. Met het minteken ervoor wordt het een plus: $F(x) = x\arcsin(2x) + \tfrac{1}{2}\sqrt{1 - 4x^{2}} + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(3x)$$ksql$, 1, $ksql$Weer één factor, dus weer $h'(x) = 1$ en $h(x) = x$, met $g(x) = \arctan(3x)$. Met de kettingregel is $g'(x) = \dfrac{3}{9x^{2} + 1}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(3x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arctan(3x)\,\mathrm{d}x = x\arctan(3x) - \int \dfrac{3x}{9x^{2} + 1}\,\mathrm{d}x$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Primitiveer met behulp van partieel integreren: $f(x) = \arctan(3x)$$ksql$, 3, $ksql$In die laatste integraal staat de afgeleide van de noemer bijna in de teller: $\left[9x^{2} + 1\right]' = 18x$, en $3x$ is daar $\tfrac{1}{6}$ van. Dus $\int \dfrac{3x}{9x^{2} + 1}\,\mathrm{d}x = \tfrac{1}{6}\ln\left(9x^{2} + 1\right)$ — een logaritme, geen arctangens, want de teller is de afgeleide van de noemer. Samen: $F(x) = x\arctan(3x) - \tfrac{1}{6}\ln\left(9x^{2} + 1\right) + c$. Controle: differentieer $F$ en je krijgt $f$ terug.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \arcsin(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een kale $\arcsin$ of $\arctan$ → partieel integreren. Die twee kun je niet zomaar primitiveren, maar wél differentiëren, dus zet ze op de plek van $g$ en maak er zelf een product van met $h'(x) = 1$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \arcsin(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Maak er een product van: $h'(x) = 1$, dus $h(x) = x$, en $g(x) = \arcsin(x)$ met $g'(x) = \dfrac{1}{\sqrt{1 - x^{2}}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \arcsin(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\int \arcsin(x)\,\mathrm{d}x = x\arcsin(x) - \int \dfrac{x}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$. Die laatste integraal is $-\sqrt{1 - x^{2}}$, want $\left[\sqrt{1 - x^{2}}\right]' = \dfrac{-x}{\sqrt{1 - x^{2}}}$. De twee mintekens maken er een plus van: $F(x) = x\arcsin(x) + \sqrt{1 - x^{2}}$.$ksql$),
  ('k3c_primitiveren', 'k3c_partieel', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} \arcsin(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\left[x\arcsin(x) + \sqrt{1 - x^{2}}\right]_{0}^{1} = \left(1 \cdot \tfrac{1}{2}\pi + 0\right) - \left(0 + 1\right) = \tfrac{1}{2}\pi - 1$. Bij $x = 1$ is de wortel $0$ en bij $x = 0$ is de $\arcsin$-term $0$, dus er blijft van allebei maar één stuk over.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$Er staat al precies de standaardvorm: kern $x$ en $a = 1$. De rare bovengrens is een hint dat er straks een mooie waarde uit de tabel komt.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $F(x) = \arcsin(x)$, zonder integratieconstante — bij een bepaalde integraal valt die toch weg.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{2}} \dfrac{1}{\sqrt{1 - x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in: $\big[\arcsin(x)\big]_{0}^{\frac{1}{2}\sqrt{2}} = \arcsin\left(\tfrac{1}{2}\sqrt{2}\right) - \arcsin(0) = \tfrac{1}{4}\pi - 0 = \tfrac{1}{4}\pi$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}} \dfrac{1}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{1 - (\ldots)^{2}}$ in de noemer → de standaardvorm $\dfrac{1}{\sqrt{1 - x^{2}}}$ geeft $\arcsin(x) + c$. Lees eerst de kern af; de regel voor $f(ax + b)$ zegt dat je daarna nog door $a$ moet delen.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}} \dfrac{1}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$$4x^{2} = (2x)^{2}$, dus er staat $\dfrac{1}{\sqrt{1 - (2x)^{2}}}$: kern $2x$ met $a = 2$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}} \dfrac{1}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$De regel voor $f(ax + b)$ zegt: primitiveer alsof er $x$ staat en deel daarna door $a$. Delen door $2$ geeft $F(x) = \tfrac{1}{2}\arcsin(2x)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}} \dfrac{1}{\sqrt{1 - 4x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Bij $x = \tfrac{1}{4}$ is de kern $\tfrac{1}{2}$ en bij $x = 0$ is de kern $0$: $\tfrac{1}{2}\arcsin\left(\tfrac{1}{2}\right) - \tfrac{1}{2}\arcsin(0) = \tfrac{1}{2} \cdot \tfrac{1}{6}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{16 - x^{2}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: een breuk met $\sqrt{a^{2} - x^{2}}$ in de noemer → nog geen standaardvorm, want achter de $1$ hoort een min en vóór het kwadraat een $1$. Haal eerst $a$ buiten de wortel: $\sqrt{a^{2} - x^{2}} = a\sqrt{1 - \left(\tfrac{x}{a}\right)^{2}}$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{16 - x^{2}}}\,\mathrm{d}x$$ksql$, 1, $ksql$Haal de $4$ buiten de wortel: $\sqrt{16 - x^{2}} = 4\sqrt{1 - \left(\tfrac{1}{4}x\right)^{2}}$. Dus de integrand is $\dfrac{\tfrac{1}{4}}{\sqrt{1 - \left(\frac{1}{4}x\right)^{2}}}$, met kern $\tfrac{1}{4}x$ en $a = \tfrac{1}{4}$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{16 - x^{2}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Delen door $\tfrac{1}{4}$ is vermenigvuldigen met $4$, dus $\tfrac{1}{4} \cdot 4\arcsin\left(\tfrac{1}{4}x\right) = \arcsin\left(\tfrac{1}{4}x\right)$: $F(x) = \arcsin\left(\tfrac{1}{4}x\right)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{-2}^{2} \dfrac{1}{\sqrt{16 - x^{2}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Bij $x = 2$ is de kern $\tfrac{1}{2}$ en bij $x = -2$ is de kern $-\tfrac{1}{2}$: $\arcsin\left(\tfrac{1}{2}\right) - \arcsin\left(-\tfrac{1}{2}\right) = \tfrac{1}{6}\pi + \tfrac{1}{6}\pi = \tfrac{1}{3}\pi$. Let op het dubbele minteken bij de ondergrens.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{6}} \dfrac{x}{\sqrt{9 - x^{4}}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eerst een primitieve zoeken, daarna de grenzen invullen. Het antwoord blijft exact. Buitenste schil: onder de wortel staat een getal min $x^{4}$, en in de teller staat een $x$ → eerst het getal buiten de wortel halen, daarna substitueren.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{6}} \dfrac{x}{\sqrt{9 - x^{4}}}\,\mathrm{d}x$$ksql$, 1, $ksql$Haal de $3$ buiten de wortel: $\sqrt{9 - x^{4}} = 3\sqrt{1 - \left(\tfrac{x^{2}}{3}\right)^{2}}$, want $\tfrac{x^{4}}{9} = \left(\tfrac{x^{2}}{3}\right)^{2}$. Neem $g(x) = \tfrac{x^{2}}{3}$, dan is $g'(x) = \tfrac{2}{3}x$. In de teller staat $\tfrac{1}{3}x$, en dat is $\tfrac{1}{2}g'$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{6}} \dfrac{x}{\sqrt{9 - x^{4}}}\,\mathrm{d}x$$ksql$, 2, $ksql$Naar $g$ staat er dus $\tfrac{1}{2}\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \tfrac{1}{2}\arcsin(g)$, dus $F(x) = \tfrac{1}{2}\arcsin\left(\tfrac{x^{2}}{3}\right)$.$ksql$),
  ('k3c_bepaald', 'k3c_bepaald_exact', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\sqrt{6}} \dfrac{x}{\sqrt{9 - x^{4}}}\,\mathrm{d}x$$ksql$, 3, $ksql$Vul de grenzen in. Bij $x = \tfrac{1}{2}\sqrt{6}$ is $x^{2} = \tfrac{6}{4} = 1\tfrac{1}{2}$, dus de kern is $\tfrac{1\frac{1}{2}}{3} = \tfrac{1}{2}$; bij $x = 0$ is de kern $0$. Dat geeft $\tfrac{1}{2}\arcsin\left(\tfrac{1}{2}\right) - 0 = \tfrac{1}{2} \cdot \tfrac{1}{6}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3}{\sqrt{9 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: het vlakdeel tussen de grafiek, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$ wordt $O(V) = \displaystyle\int_{0}^{1\frac{1}{2}} \dfrac{3}{\sqrt{9 - x^{2}}}\,\mathrm{d}x$. Op $[0; 1\tfrac{1}{2}]$ is $f$ positief, dus er hoeft geen minteken bij.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3}{\sqrt{9 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Haal de $3$ buiten de wortel: $\sqrt{9 - x^{2}} = 3\sqrt{1 - \left(\tfrac{1}{3}x\right)^{2}}$. De integrand wordt $\dfrac{1}{\sqrt{1 - \left(\frac{1}{3}x\right)^{2}}}$, met kern $\tfrac{1}{3}x$ en $a = \tfrac{1}{3}$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3}{\sqrt{9 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Deel 2: delen door $\tfrac{1}{3}$ is vermenigvuldigen met $3$, dus $F(x) = 3\arcsin\left(\tfrac{1}{3}x\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3}{\sqrt{9 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = 1\tfrac{1}{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Deel 3: de grenzen invullen. Bij $x = 1\tfrac{1}{2}$ is de kern $\tfrac{1}{2}$ en bij $x = 0$ is de kern $0$: $O(V) = 3\arcsin\left(\tfrac{1}{2}\right) - 3\arcsin(0) = 3 \cdot \tfrac{1}{6}\pi = \tfrac{1}{2}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x}{\sqrt{16 - x^{4}}}$, de $x$-as en de lijn $x = \sqrt{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: er staat maar één lijn bij, dus de andere grens moet je zelf vinden. De grafiek snijdt de $x$-as waar de teller $0$ is, dus bij $x = 0$: $O(V) = \displaystyle\int_{0}^{\sqrt{2}} \dfrac{x}{\sqrt{16 - x^{4}}}\,\mathrm{d}x$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x}{\sqrt{16 - x^{4}}}$, de $x$-as en de lijn $x = \sqrt{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Haal de $4$ buiten de wortel: $\sqrt{16 - x^{4}} = 4\sqrt{1 - \left(\tfrac{x^{2}}{4}\right)^{2}}$. Neem $g(x) = \tfrac{x^{2}}{4}$, dan is $g'(x) = \tfrac{1}{2}x$. In de teller staat na het delen $\tfrac{1}{4}x$, en dat is $\tfrac{1}{2}g'$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x}{\sqrt{16 - x^{4}}}$, de $x$-as en de lijn $x = \sqrt{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Deel 2: naar $g$ staat er $\tfrac{1}{2}\int \dfrac{1}{\sqrt{1 - g^{2}}}\,\mathrm{d}g = \tfrac{1}{2}\arcsin(g)$, dus $F(x) = \tfrac{1}{2}\arcsin\left(\tfrac{x^{2}}{4}\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x}{\sqrt{16 - x^{4}}}$, de $x$-as en de lijn $x = \sqrt{2}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Deel 3: de grenzen invullen. Bij $x = \sqrt{2}$ is $x^{2} = 2$, dus de kern is $\tfrac{2}{4} = \tfrac{1}{2}$; bij $x = 0$ is de kern $0$. Dat geeft $O(V) = \tfrac{1}{2}\arcsin\left(\tfrac{1}{2}\right) = \tfrac{1}{2} \cdot \tfrac{1}{6}\pi = \tfrac{1}{12}\pi$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{\sqrt{25 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 5$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 0, $ksql$Hier spelen alle drie de delen van de driedeling: eerst het verhaaltje vertalen naar een integraal (deel 1), dan die integraal berekenen (deel 2), en daarna nog iets doen met de uitkomst (deel 3). Deel 1: $O(V_p) = \displaystyle\int_{0}^{p} \dfrac{4}{\sqrt{25 - x^{2}}}\,\mathrm{d}x$. De bovengrens is nu een letter; verder verandert er niets. De voorwaarde $p < 5$ staat erbij omdat $f$ buiten $\langle-5, 5\rangle$ niet bestaat.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{\sqrt{25 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 5$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 1, $ksql$Haal de $5$ buiten de wortel: $\sqrt{25 - x^{2}} = 5\sqrt{1 - \left(\tfrac{1}{5}x\right)^{2}}$. De integrand wordt $\dfrac{\tfrac{4}{5}}{\sqrt{1 - \left(\frac{1}{5}x\right)^{2}}}$, met kern $\tfrac{1}{5}x$ en $a = \tfrac{1}{5}$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{\sqrt{25 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 5$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 2, $ksql$Deel 2: delen door $\tfrac{1}{5}$ is vermenigvuldigen met $5$, dus $F(x) = \tfrac{4}{5} \cdot 5\arcsin\left(\tfrac{1}{5}x\right) = 4\arcsin\left(\tfrac{1}{5}x\right)$. Omdat $\arcsin(0) = 0$ is $O(V_p) = 4\arcsin\left(\tfrac{1}{5}p\right)$.$ksql$),
  ('k3c_toepassing', 'k3c_oppervlakte', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4}{\sqrt{25 - x^{2}}}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $0 < p < 5$. Bereken exact de waarde van $p$ waarvoor $O(V_p) = \pi$.$ksql$, 3, $ksql$Deel 3: de vergelijking oplossen. $4\arcsin\left(\tfrac{1}{5}p\right) = \pi$ geeft $\arcsin\left(\tfrac{1}{5}p\right) = \tfrac{1}{4}\pi$. Die hoek ligt tussen $-\tfrac{1}{2}\pi$ en $\tfrac{1}{2}\pi$, dus er is een oplossing: $\tfrac{1}{5}p = \sin\left(\tfrac{1}{4}\pi\right) = \tfrac{1}{2}\sqrt{2}$, dus $p = 2\tfrac{1}{2}\sqrt{2} \approx 3{,}54$. Dat is inderdaad kleiner dan $5$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_waarden' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_arcsinus' AND site = 'integralen'));
  IF n <> 3 THEN RAISE EXCEPTION 'Cluster k3c_waarden hoort 3 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_vergelijking' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_arcsinus' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster k3c_vergelijking hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_standaard' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 5 THEN RAISE EXCEPTION 'Cluster k3c_standaard hoort 5 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_kern' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster k3c_kern hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_partieel' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_primitiveren' AND site = 'integralen'));
  IF n <> 3 THEN RAISE EXCEPTION 'Cluster k3c_partieel hoort 3 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_bepaald_exact' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_bepaald' AND site = 'integralen'));
  IF n <> 4 THEN RAISE EXCEPTION 'Cluster k3c_bepaald_exact hoort 4 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k3c_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k3c_toepassing' AND site = 'integralen'));
  IF n <> 3 THEN RAISE EXCEPTION 'Cluster k3c_oppervlakte hoort 3 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k3c_arcsinus', 'k3c_primitiveren', 'k3c_bepaald', 'k3c_toepassing');
  IF n <> 104 THEN RAISE EXCEPTION 'Deze topics horen samen 104 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
